  "var_renames": {},
  "struct_hints": [
    {
      "offset": 68,
      "meaning": "pointer to status/station context whose flag word controls rate selection"
    },
    {
      "offset": 8,
      "meaning": "status flags; bit 0x200 selects a fixed/global rate encoding"
    },
    {
      "offset": 44,
      "meaning": "pointer to a context or descriptor whose signed offset-60 field validates cached rate selection"
    },
    {
      "offset": 60,
      "meaning": "signed state/index field used to choose the cached transmit rate"
    },
    {
      "offset": 580,
      "meaning": "cached transmit rate value"
    },
    {
      "offset": 309,
      "meaning": "MCS/rate byte used to derive a fallback transmit-rate encoding"
